 12	package com.sun.fortress.interpreter.evaluator.tasks;
 13	
 14	import com.sun.fortress.exceptions.transactions.AbortedException;
 15	import com.sun.fortress.exceptions.transactions.PanicException;
 16	import com.sun.fortress.interpreter.evaluator.transactions.Transaction;
 17	import java.util.concurrent.RecursiveAction;
 18	
 19	import java.util.concurrent.atomic.AtomicInteger;
 20	
 21	public abstract class BaseTask extends RecursiveAction {
 22	    Throwable err = null;
 23	    Transaction transaction = null;
 24	    final private int depth;
 25	    final private BaseTask parent;
 26	
 27	    // Debugging
 28	    private static Boolean debug = false;
 29	    private static AtomicInteger counter = new AtomicInteger();
 30	    private int count;
 31	    String name;
 32	
 33	    public BaseTask(BaseTask p) {
 34	        parent = p;
 35	        transaction = p.transaction();
 36	        depth = p.depth() + 1;
 37	        if (debug) {
 38	            count = counter.getAndIncrement();
 39	            name = p.name() + "." + count;
 40	        } else {
 41	            name = "BaseTask";
 42	            count = 0;
 43	        }
 44	    }
 45	
 46	    public int depth() {
 47	        return depth;
 48	    }
 49	
 50	    public int count() {
 51	        return count;
 52	    }
 53	
 54	    public String name() {
 55	        return name;
 56	    }
 57	
 58	    // For primordial evaluator task
 59	    public BaseTask() {
 60	        parent = null;
 61	        transaction = null;
 62	        depth = 0;
 63	        count = 0;
 64	        name = "0";
 65	    }
 66	
 67	    public BaseTask parent() {
 68	        return parent;
 69	    }
 70	
 71	    public int transactionNesting() {
 72	        if (transaction == null) return 0;
 73	        else return transaction.getNestingDepth();
 74	    }
 75	
 76	    public Transaction transaction() {
 77	        return transaction;
 78	    }
 79	
 80	    public Boolean inATransaction() {
 81	        return (transaction != null);
 82	    }
 83	
 84	    /**
 85	     * Can this transaction still commit?
 86	     * This method may be called at any time, not just at transaction end,
 87	     * so we do not clear the onValidateOnce table.
 88	     *
 89	     * @return true iff transaction might still commit
 90	     */
 91	    public boolean validate() {
 92	        try {
 93	            if (transaction == null) throw new PanicException(
 94	                    Thread.currentThread().getName() + "Attempting to validate null transaction");
 95	            return transaction.validate();
 96	        }
 97	        catch (AbortedException ex) {
 98	            return false;
 99	        }
100	    }
101	
102	    /**
103	     * Starts a new transaction.
104	     */
105	    public void beginTransaction() {
106	        if (transaction == null) {
107	            transaction = new Transaction();
108	        } else if (!transaction.isActive()) throw new AbortedException(transaction,
109	                                                                       "Parent death detected in beginTransaction");
110	        else {
111	            Transaction parent = transaction;
112	            Transaction child = new Transaction(transaction);
113	            transaction = child;
114	
115	            if (!parent.isActive()) {
116	                child.abort();
117	                transaction = parent;
118	                throw new AbortedException(parent, "Parent death detected in beginTransaction");
119	            }
120	        }
121	    }
122	
123	    /**
124	     * Attempts to commit the current transaction of the invoking
125	     * <code>Thread</code>.
126	     *
127	     * @return whether commit succeeded.
128	     */
129	    public boolean commitTransaction() {
130	        if (validate() && transaction.commit()) {
131	            return true;
132	        }
133	        abortTransaction();
134	        return false;
135	    }
136	
137	    /**
138	     * Aborts the current transaction of the invoking <code>Thread</code>.
139	     * Does not end transaction, but ensures it will never commit.
140	     */
141	    public void abortTransaction() {
142	        if (transaction != null && transaction.isActive()) {
143	            transaction.abort();
144	        }
145	    }
146	
147	    public void giveUpTransaction() {
148	        if (transaction == null) {
149	            throw new PanicException(Thread.currentThread().getName() + "Giving up null transaction");
150	        }
151	        //    if (transaction.isActive()) {
152	        //        throw new PanicException(Thread.currentThread().getName() + "How did an active transaction escape?");
153	        //    }
154	        transaction = transaction.getParent();
155	    }
156	
157	    public void recordException(Throwable t) {
158	        err = t;
159	    }
160	
161	    public boolean causedException() {
162	        return err != null;
163	    }
164	
165	    public Throwable taskException() {
166	        return err;
167	    }
168	
169	    public abstract void print();
170	
171	    public static void printTaskTrace() {
172	        BaseTask task = FortressTaskRunner.getTask();
173	        while (task != null) {
174	            task.print();
175	            task = task.parent();
176	        }
177	    }
178	
179	    public String toString() {
180	        return "[BaseTask" + name() + ":" + transaction + "]";
181	    }
182	
183	}
