195	package com.sun.fortress.interpreter.evaluator.tasks;
196	
197	import com.sun.fortress.exceptions.FortressError;
198	import com.sun.fortress.exceptions.transactions.AbortedException;
199	import com.sun.fortress.exceptions.transactions.OrphanedException;
200	import com.sun.fortress.interpreter.evaluator.transactions.ContentionManager;
201	import com.sun.fortress.interpreter.evaluator.transactions.Transaction;
202	import com.sun.fortress.interpreter.evaluator.transactions.manager.GreedyManager;
203	import java.util.concurrent.ForkJoinWorkerThread;
204	
205	import java.util.concurrent.Callable;
206	
207	public class FortressTaskRunner extends ForkJoinWorkerThread {
208	
209	    private static ContentionManager manager = new GreedyManager();
210	    public volatile BaseTask task;
211	    private int retries;
212	    private static long startTime = System.currentTimeMillis();
213	
214	    public int retries() {
215	        return retries;
216	    }
217	
218	    private static void incRetries() {
219	        FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
220	        runner.retries += 1;
221	    }
222	
223	    private static void resetRetries() {
224	        FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
225	        runner.retries = 0;
226	    }
227	
228	    private static int getRetries() {
229	        FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
230	        return runner.retries;
231	    }
232	
233	    public BaseTask task() {
234	        return task;
235	    }
236	
237	    public static BaseTask getTask() {
238	        FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
239	        return runner.task();
240	    }
241	
242	    public static Transaction transaction() {
243	        return getTask().transaction();
244	    }
245	
246	    public static boolean inATransaction() {
247	        return transaction() != null;
248	    }
249	
250	    public void setTask(BaseTask t) {
251	        task = t;
252	    }
253	
254	    public static void setCurrentTask(BaseTask task) {
255	        FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
256	        runner.setTask(task);
257	    }
258	
259	
260	    public FortressTaskRunner(FortressTaskRunnerGroup group) {
261	        super(group);
262	        retries = 0;
263	    }
264	
265	    /**
266	     * Tests whether the current transaction can still commit.  Does not
267	     * actually end the transaction (either <code>commitTransaction</code> or
268	     * <code>abortTransaction</code> must still be called).  The contention
269	     * manager of the invoking thread is notified if the onValidate fails
270	     * because a <code>TMObject</code> opened for reading was invalidated.
271	     *
272	     * @return whether the current transaction may commit successfully.
273	     */
274	    public static boolean validate() {
275	        return transaction().validate();
276	    }
277	
278	    /**
279	     * Gets the current transaction, if any, of the invoking <code>Thread</code>.
280	     *
281	     * @return the current thread's current transaction; <code>null</code> if
282	     *         there is no current transaction.
283	     */
284	    static public Transaction getTransaction() {
285	        return transaction();
286	    }
287	
288	    /**
289	     * Gets the contention manager
290	     *
291	     * @return the contention manager
292	     */
293	
294	    public static ContentionManager getContentionManager() {
295	        return manager;
296	    }
297	
298	    public static void debugPrintln(String msg) {
299	        FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
300	        long t = System.currentTimeMillis() - startTime;
301	        System.out.println(runner.getName() + ":" + runner.task() + ":" + t + "ms " + msg);
302	    }
303	
304	    public static <T> T doItOnce(Callable<T> xaction) throws AbortedException, Exception {
305	        getTask().beginTransaction();
306	        try {
307	            T result = xaction.call();
308	            if (getTask().commitTransaction()) {
309	                return result;
310	            } else {
311	                getTask().abortTransaction();
312	                throw new AbortedException(transaction(), " commit failed");
313	            }
314	        }
315	        catch (FortressError fe) {
316	            throw fe;
317	        }
318	        finally {
319	            getTask().giveUpTransaction();
320	        }
321	    }
322	
323	    /**
324	     * Execute a transaction
325	     *
326	     * @param xaction execute this object's <CODE>call()</CODE> method.
327	     * @return result of <CODE>call()</CODE> method
328	     */
329	
330	    public static <T> T doIt(Callable<T> xaction) throws Exception {
331	        resetRetries();
332	        while (true) {
333	            // Someday figure out how aborted transactions get this far...
334	            Transaction me = getTransaction();
335	            if (me != null && !me.isActive()) {
336	                throw new AbortedException(me, "Got to doit with an aborted current transaction");
337	            }
338	            try {
339	                T result = doItOnce(xaction);
340	                return result;
341	            }
342	            catch (OrphanedException oe) {
343	                if (oe.getTransaction() != null && oe.getTransaction() != me && oe.getTransaction().getParent() != me)
344	                    throw new RuntimeException(
345	                            Thread.currentThread().getName() + " OE transaction  = " + oe + " me = " + me +
346	                            " oe parent = " + oe.getTransaction().getParent());
347	            }
348	            catch (AbortedException ae) {
349	                if (ae.getTransaction() != null && ae.getTransaction() != me && ae.getTransaction().getParent() != me)
350	                    throw new RuntimeException(
351	                            Thread.currentThread().getName() + " AE transaction  = " + ae + " me = " + me +
352	                            " ae parent = " + ae.getTransaction().getParent());
353	            }
354	            finally {
355	                incRetries();
356	            }
357	        }
358	    }
359	
360	    /**
361	     * get thread ID for debugging
362	     *
363	     * @return unique id
364	     */
365	    public static int getID() {
366	        FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
367	        return runner.hashCode();
368	    }
369	}

