 12	package com.sun.fortress.interpreter.evaluator.transactions;
 13	
 14	import com.sun.fortress.exceptions.transactions.PanicException;
 15	import com.sun.fortress.interpreter.env.ReferenceCell;
 16	import com.sun.fortress.interpreter.evaluator.tasks.FortressTaskRunner;
 17	import com.sun.fortress.interpreter.evaluator.values.FValue;
 18	
 19	import java.util.ArrayList;
 20	import java.util.Enumeration;
 21	import java.util.List;
 22	import java.util.concurrent.ConcurrentHashMap;
 23	import java.util.concurrent.atomic.AtomicInteger;
 24	import java.util.concurrent.atomic.AtomicReference;
 25	
 26	/**
 27	 * Transaction.java
 28	 * Keeps a transaction's status and contention manager.
 29	 */
 30	
 31	public class Transaction {
 32	
 33	    /**
 34	     * Possible transaction status
 35	     */
 36	    private enum Status {
 37	        ORPHANED, ABORTED, ACTIVE, COMMITTED
 38	    }
 39	
 40	    ;
 41	    private Transaction parent;
 42	    private volatile List<Transaction> children;
 43	    /**
 44	     * Updater for status
 45	     */
 46	    private volatile AtomicReference<Status> myStatus;
 47	    private int nestingDepth;
 48	    private int count;
 49	    private static AtomicInteger counter = new AtomicInteger();
 50	
 51	    public static final boolean debug = false;
 52	
 53	    // Used for debugging
 54	    private ConcurrentHashMap<ReferenceCell, ConcurrentHashMap<FortressTaskRunner, String>> updates;
 55	
 56	
 57	    /**
 58	     * Creates a new, active transaction.
 59	     */
 60	    public Transaction() {
 61	        parent = null;
 62	        children = new ArrayList<Transaction>();
 63	        nestingDepth = 0;
 64	        myStatus = new AtomicReference(Status.ACTIVE);
 65	        count = counter.getAndIncrement();
 66	
 67	        if (debug) {
 68	            updates = new ConcurrentHashMap<ReferenceCell, ConcurrentHashMap<FortressTaskRunner, String>>();
 69	        }
 70	    }
 71	
 72	    public Transaction(Transaction p) {
 73	        parent = p;
 74	        children = new ArrayList<Transaction>();
 75	        count = counter.getAndIncrement();
 76	
 77	        if (debug) {
 78	            updates = new ConcurrentHashMap<ReferenceCell, ConcurrentHashMap<FortressTaskRunner, String>>();
 79	
 80	        }
 81	
 82	        if (p == null) {
 83	            nestingDepth = 0;
 84	            myStatus = new AtomicReference(Status.ACTIVE);
 85	        } else if (p.isActive()) {
 86	            nestingDepth = p.getNestingDepth() + 1;
 87	            myStatus = new AtomicReference(Status.ACTIVE);
 88	            p.addChild(this);
 89	        } else {
 90	            nestingDepth = p.getNestingDepth() + 1;
 91	            myStatus = new AtomicReference(Status.ORPHANED);
 92	        }
 93	
 94	    }
 95	
 96	    // Used for debugging, called from ReferenceCell
 97	    public void addRead(ReferenceCell rc, FValue f) {
 98	        if (debug) {
 99	            FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
100	            updates.putIfAbsent(rc, new ConcurrentHashMap<FortressTaskRunner, String>());
101	            ConcurrentHashMap<FortressTaskRunner, String> m = updates.get(rc);
102	            if (!m.containsKey(runner)) {
103	                m.put(runner, "(read " + f + ")");
104	            } else {
105	                m.put(runner, m.get(runner) + "(read " + f + ")");
106	            }
107	        }
108	    }
109	
110	    // Used for debugging, called from ReferenceCell
111	    public void addWrite(ReferenceCell rc, FValue f) {
112	        if (debug) {
113	            FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
114	            updates.putIfAbsent(rc, new ConcurrentHashMap<FortressTaskRunner, String>());
115	            ConcurrentHashMap<FortressTaskRunner, String> m = updates.get(rc);
116	            if (!m.containsKey(runner)) {
117	                m.put(runner, "( write " + f + ")");
118	            } else {
119	                String temp = m.get(runner) + "(write " + f + ")";
120	                m.put(runner, temp);
121	            }
122	        }
123	    }
124	
125	    // Used for debugging, called from ReferenceCell
126	    public void mergeUpdates(String s, Transaction t, ReferenceCell rc) {
127	        if (debug) {
128	            FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
129	            updates.putIfAbsent(rc, new ConcurrentHashMap<FortressTaskRunner, String>());
130	            ConcurrentHashMap<FortressTaskRunner, String> m = updates.get(rc);
131	            if (!m.containsKey(runner)) m.put(runner, s);
132	            else m.put(runner, m.get(runner) + s);
133	        }
134	    }
135	
136	    public int getNestingDepth() {
137	        return nestingDepth;
138	    }
139	
140	    public long getID() {
141	        return count;
142	    }
143	
144	
145	    /* Access the transaction's current status.
146	     * @return current transaction status
147	     */
148	    private Status getStatus() {
149	        return myStatus.get();
150	    }
151	
152	    /**
153	     * Tests whether transaction is active.
154	     *
155	     * @return whether transaction is active
156	     */
157	    public boolean isActive() {
158	        return getStatus() == Status.ACTIVE;
159	    }
160	
161	    /**
162	     * Tests whether transaction is aborted.
163	     *
164	     * @return whether transaction is aborted
165	     */
166	    public boolean isAborted() {
167	        return getStatus() == Status.ABORTED;
168	    }
169	
170	    /**
171	     * Tests whether transaction is committed.
172	     *
173	     * @return whether transaction is committed
174	     */
175	    public boolean isCommitted() {
176	        return getStatus() == Status.COMMITTED;
177	    }
178	
179	    /**
180	     * Tests whether transaction is abandoned
181	     *
182	     * @return whether transaction is abandoned
183	     */
184	
185	    public boolean isOrphaned() {
186	        return getStatus() == Status.ORPHANED;
187	    }
188	
189	    public boolean addChild(Transaction c) {
190	        if (isActive()) {
191	            synchronized (children) {
192	                children.add(c);
193	            }
194	            return true;
195	        } else return false;
196	    }
197	
198	    public Transaction getParent() {
199	        return parent;
200	    }
201	
202	    /**
203	     * Tests whether transaction is committed or active.
204	     *
205	     * @return whether transaction is committed or active
206	     */
207	    public boolean validate() {
208	        Status st = getStatus();
209	
210	        switch (st) {
211	            case COMMITTED:
212	                throw new PanicException("committed transaction still running");
213	            case ACTIVE:
214	                return true;
215	            case ABORTED:
216	                return false;
217	            case ORPHANED:
218	                return false;
219	            default:
220	                throw new PanicException("unexpected transaction state: " + getStatus());
221	        }
222	    }
223	
224	    /**
225	     * Tries to commit transaction
226	     *
227	     * @return whether transaction was committed
228	     */
229	    public boolean commit() {
230	        while (myStatus.get() == Status.ACTIVE) {
231	            if (myStatus.compareAndSet(Status.ACTIVE, Status.COMMITTED)) {
232	                if (debug) {
233	                    if (parent == null) {
234	                        Enumeration<ReferenceCell> temp = updates.keys();
235	                        while (temp.hasMoreElements()) {
236	                            ReferenceCell key = temp.nextElement();
237	                            ConcurrentHashMap<FortressTaskRunner, String> ups = updates.get(key);
238	                            FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
239	                            String mine = ups.get(runner);
240	                        }
241	                    } else {
242	                        Enumeration<ReferenceCell> temp = updates.keys();
243	                        while (temp.hasMoreElements()) {
244	                            ReferenceCell key = temp.nextElement();
245	                            ConcurrentHashMap<FortressTaskRunner, String> ups = updates.get(key);
246	                            FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
247	                            String mine = ups.get(runner);
248	                            parent.mergeUpdates(mine, this, key);
249	                        }
250	                    }
251	                }
252	
253	                synchronized (children) {
254	                    children.clear();
255	                }
256	                return true;
257	            }
258	        }
259	        return false;
260	    }
261	
262	    /**
263	     * Tries to abort transaction
264	     *
265	     * @return whether transaction was aborted (not necessarily by this call)
266	     */
267	    public boolean abort() {
268	        while (myStatus.get() == Status.ACTIVE) {
269	            if (myStatus.compareAndSet(Status.ACTIVE, Status.ABORTED)) {
270	                synchronized (children) {
271	                    for (Transaction child : children) {
272	                        child.orphan();
273	                    }
274	                    children.clear();
275	                }
276	                return true;
277	            }
278	        }
279	        if (isActive()) throw new RuntimeException("Transaction " + this + " is active and didn't get aborted ?");
280	        return false;
281	    }
282	
283	    public boolean orphan() {
284	        if (myStatus.compareAndSet(Status.ACTIVE, Status.ORPHANED)) {
285	            synchronized (children) {
286	                for (Transaction child : children) {
287	                    child.orphan();
288	                }
289	                children.clear();
290	            }
291	            return true;
292	        } else if (myStatus.compareAndSet(Status.ABORTED, Status.ORPHANED)) {
293	            synchronized (children) {
294	                for (Transaction child : children) {
295	                    child.orphan();
296	                }
297	            }
298	            return false;
299	        } else if (myStatus.compareAndSet(Status.COMMITTED, Status.ORPHANED)) {
300	            synchronized (children) {
301	                for (Transaction child : children) {
302	                    child.orphan();
303	                }
304	            }
305	            return false;
306	        } else return false;
307	    }
308	
309	
310	    /**
311	     * Returns a string representation of this transaction
312	     *
313	     * @return the string representcodes[ation
314	     */
315	    public String toString() {
316	        switch (getStatus()) {
317	            case COMMITTED:
318	                return "[T" + count + ":committed, p=" + getParent() + "=>" + getNestingDepth() + "]";
319	            case ABORTED:
320	                return "[T" + count + ":aborted,p=" + getParent() + "=>" + getNestingDepth() + "]";
321	            case ACTIVE:
322	                return "[T" + count + ":active,p=" + getParent() + "=>" + getNestingDepth() + "]";
323	            case ORPHANED:
324	                return "[T" + count + ":orphaned ]";
325	            default:
326	                return "[T" + count + "[???]]";
327	        }
328	    }
329	
330	    /**
331	     * This transaction's contention manager
332	     *
333	     * @return the manager
334	     */
335	    public ContentionManager getContentionManager() {
336	        return FortressTaskRunner.getContentionManager();
337	    }
338	
339	    public boolean isAncestorOf(Transaction t) {
340	        Transaction current = t;
341	        while (current != null && current != this) {
342	            current = current.getParent();
343	        }
344	        if (current == this) {
345	            return true;
346	        } else {
347	            return false;
348	        }
349	    }
350	}

