 12	package com.sun.fortress.interpreter.env;
 13	
 14	import static com.sun.fortress.exceptions.InterpreterBug.bug;
 15	import com.sun.fortress.exceptions.transactions.AbortedException;
 16	import com.sun.fortress.exceptions.transactions.OrphanedException;
 17	import com.sun.fortress.interpreter.evaluator.tasks.FortressTaskRunner;
 18	import com.sun.fortress.interpreter.evaluator.transactions.Transaction;
 19	import com.sun.fortress.interpreter.evaluator.types.FType;
 20	import com.sun.fortress.interpreter.evaluator.values.FValue;
 21	
 22	import java.util.concurrent.atomic.AtomicInteger;
 23	
 24	/**
 25	 * What the interpreter stores mutable things (fields, variables)
 26	 * in.  It will eventually acquire transactional semantics.
 27	 */
 28	
 29	public class ReferenceCell extends IndirectionCell {
 30	    private FType theType;
 31	    ValueNode node;
 32	
 33	    // for debugging
 34	    static final AtomicInteger counter = new AtomicInteger(0);
 35	    final int id;
 36	
 37	    public ReferenceCell() {
 38	        super();
 39	        node = ValueNode.nullValueNode;
 40	        id = counter.getAndIncrement();
 41	    }
 42	
 43	    public ReferenceCell(FType t) {
 44	        super();
 45	        theType = t;
 46	        node = ValueNode.nullValueNode;
 47	        id = counter.getAndIncrement();
 48	    }
 49	
 50	    public ReferenceCell(FType t, FValue v) {
 51	        super();
 52	        theType = t;
 53	        node = new ValueNode(v, FortressTaskRunner.getTransaction(), null, ValueNode.nullValueNode);
 54	        id = counter.getAndIncrement();
 55	    }
 56	
 57	    public FType getType() {
 58	        return theType;
 59	    }
 60	
 61	    public String toString() {
 62	        return "ReferenceCell" + id;
 63	    }
 64	
 65	    private boolean transactionIsCommitted(Transaction w) {
 66	        if (w == null) return true;
 67	        else if (w.isCommitted()) return true;
 68	        return false;
 69	    }
 70	
 71	    private boolean transactionIsAbortedOrOrphaned(Transaction w) {
 72	        if (w == null) return false;
 73	        else if (w.isAborted()) return true;
 74	        else if (w.isOrphaned()) return true;
 75	        else return false;
 76	    }
 77	
 78	    private boolean transactionIsNotActive(Transaction w) {
 79	        if (w == null) return false;
 80	        else if (w.isAborted()) return true;
 81	        else if (w.isOrphaned()) return true;
 82	        else if (w.isCommitted()) return true;
 83	        else return false;
 84	    }
 85	
 86	
 87	    private synchronized void cleanup() {
 88	        Transaction w = node.getWriter();
 89	        if (Transaction.debug) FortressTaskRunner.debugPrintln("Cleanup:" + this + " start with node = " + node);
 90	        while (w != null && transactionIsNotActive(w)) {
 91	            if (transactionIsAbortedOrOrphaned(w)) {
 92	                node = node.getOld();
 93	            } else {
 94	                assert (transactionIsCommitted(w));
 95	                Transaction p = w.getParent();
 96	                ValueNode old = node.getOld();
 97	                if (p == null && old == null) {
 98	                    // Committed to top level, with no previous value.
 99	                    node = new ValueNode(node.getValue(), null, null, null);
100	                } else if (p == null) {
101	                    // Committed to top level.  Any readers of the committed transaction
102	                    // must be preserved.
103	                    node = new ValueNode(node.getValue(), null, old.getReaders(), null);
104	                } else if (old != null) {
105	                    // Committed to a parent transaction, must preserve readers and
106	                    // old transaction.
107	                    node = new ValueNode(node.getValue(), p, old.getReaders(), old);
108	                } else {
109	                    node = new ValueNode(node.getValue(), p, null, null);
110	                }
111	            }
112	            if (node != null) {
113	                w = node.getWriter();
114	            } else {
115	                node = ValueNode.nullValueNode;
116	                if (Transaction.debug) FortressTaskRunner.debugPrintln("Cleanup:" + this + " end with " + node);
117	                return;
118	            }
119	        }
120	        if (Transaction.debug) FortressTaskRunner.debugPrintln("Cleanup:" + this + " end with " + node);
121	    }
122	
123	    public synchronized void assignValue(FValue f2) {
124	        Transaction me = FortressTaskRunner.getTransaction();
125	        cleanup();
126	        if (Transaction.debug) FortressTaskRunner.debugPrintln(
127	                this + " assignValue start = " + node + " value = " + f2);
128	
129	        if (node == ValueNode.nullValueNode) {
130	            node = new ValueNode(f2, me, null, null);
131	        }
132	
133	        // writer is either active, or null
134	        if (me == null) { // top level assignment
135	            if (node == ValueNode.nullValueNode) node = new ValueNode(f2, me, null, null);
136	            else {
137	                ValueNode temp = node;
138	                node = new ValueNode(f2, null, null, null);
139	                temp.abortAllReadersAndWriters();
140	            }
141	        } else if (!me.isActive()) {
142	            throw new AbortedException(me, "Somebody killed me ");
143	        } else {
144	            node.resolveReadWriteConflicts();
145	            cleanup();
146	            if (!me.isActive()) throw new AbortedException(me, "Somebody killed me ");
147	
148	            Transaction w = node.getWriter();
149	            //ValueNode old = node.getOld();
150	
151	            if (w == null || w.isAncestorOf(me)) {
152	                node = new ValueNode(f2, me, node.getReaders(), node);
153	                if (Transaction.debug) me.addWrite(this, f2);
154	
155	            } else if (w.isActive()) {
156	                // Cleanup got us to a parent node with an active writer
157	                assignValue(f2);
158	            }
159	        }
160	        if (Transaction.debug) FortressTaskRunner.debugPrintln(this + " assignValue finish = " + node);
161	    }
162	
163	    public synchronized FValue getValue() {
164	        Transaction me = FortressTaskRunner.getTransaction();
165	        // Top Level transaction
166	        if (me == null) {
167	            while (node.getWriter() != null) {
168	                node.abortWriter();
169	                cleanup();
170	            }
171	            return node.getValue();
172	        }
173	
174	        if (!me.isActive()) throw new AbortedException(me, "Somebody killed me");
175	
176	        cleanup();
177	
178	        Transaction w = node.getWriter();
179	        if (w == me) {
180	            return node.getValue();
181	        } else if (w == null || w.isAncestorOf(me)) {
182	            node.addReader();
183	            if (Transaction.debug) me.addRead(this, node.getValue());
184	            return node.getValue();
185	        } else if (w.isActive()) {
186	            node.resolveWriteConflict();
187	        }
188	        return getValue();
189	    }
190	
191	    public FValue getValueNull() {
192	        FValue res = getValue();
193	        if (res == null) {
194	            FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
195	            Transaction t = runner.getTransaction();
196	            if (t.isAborted()) throw new AbortedException(t, "UhOh Someone aborted me");
197	            else if (t.isOrphaned()) throw new OrphanedException(t, "UhOh I'm an orphan");
198	            else throw new RuntimeException(
199	                        runner.getName() + " getValueNull is about to return a null value ReferenceCell = " + this +
200	                        " node = " + node + " task = " + runner.getTask());
201	        }
202	        return res;
203	    }
204	
205	
206	    public void storeValue(FValue f2) {
207	        if (node.getValue() != null) bug("Internal error, second store of indirection cell");
208	        assignValue(f2);
209	    }
210	
211	    public void storeType(FType f2) {
212	        if (theType != null) bug("Internal error, second store of type");
213	        theType = f2;
214	    }
215	
216	    public boolean isInitialized() {
217	        return getValue() != null;
218	    }
219	
220	}

