 13	
 14	import com.sun.fortress.exceptions.transactions.AbortedException;
 15	import com.sun.fortress.interpreter.evaluator.tasks.FortressTaskRunner;
 16	import com.sun.fortress.interpreter.evaluator.transactions.ReadSet;
 17	import com.sun.fortress.interpreter.evaluator.transactions.Transaction;
 18	import com.sun.fortress.interpreter.evaluator.values.FValue;
 19	
 20	import java.util.ArrayList;
 21	import java.util.List;
 22	
 23	public class ValueNode {
 24	    ValueNode old;
 25	    FValue value;
 26	    Transaction writer;
 27	    ReadSet readers;
 28	
 29	    public ValueNode(FValue v, Transaction w, ReadSet r, ValueNode o) {
 30	        old = o;
 31	        value = v;
 32	        writer = w;
 33	        readers = new ReadSet(r);
 34	    }
 35	
 36	    ValueNode() {
 37	        old = null;
 38	        value = null;
 39	        writer = null;
 40	        readers = new ReadSet();
 41	    }
 42	
 43	    public static final ValueNode nullValueNode = new ValueNode();
 44	
 45	    public String toString() {
 46	        if (this == nullValueNode) return "nullValueNode";
 47	        else return "ValueNode[" + value + ":" + writer + "::" + readers + "]";
 48	    }
 49	
 50	    public FValue getValue() {
 51	        return value;
 52	    }
 53	
 54	    public Transaction getWriter() {
 55	        return writer;
 56	    }
 57	
 58	    public ReadSet getReaders() {
 59	        return readers;
 60	    }
 61	
 62	    public ValueNode getOld() {
 63	        return old;
 64	    }
 65	
 66	    public void addReader() {
 67	        Transaction me = FortressTaskRunner.getTransaction();
 68	        if (!readers.add(me)) {
 69	            me.abort();
 70	            throw new AbortedException(me, "ReadSet Sealed : " + readers);
 71	        }
 72	    }
 73	
 74	    public void abortAllReaders() {
 75	        if (this == nullValueNode) throw new RuntimeException(
 76	                Thread.currentThread().getName() + "Trying to abort all the readers of the null value node");
 77	
 78	        readers.seal();
 79	        for (Transaction r : readers) {
 80	            r.abort();
 81	        }
 82	    }
 83	
 84	    public void abortWriter() {
 85	        if (writer != null) {
 86	            writer.abort();
 87	        }
 88	    }
 89	
 90	    public void abortAllReadersAndWriters() {
 91	        abortAllReaders();
 92	        abortWriter();
 93	    }
 94	
 95	    public void resolveReadConflicts() {
 96	        Transaction me = FortressTaskRunner.getTransaction();
 97	        List<Transaction> conflicts = new ArrayList<Transaction>();
 98	        for (Transaction reader : readers) {
 99	            if (reader.isActive() && !reader.isAncestorOf(me)) {
100	                conflicts.add(reader);
101	            }
102	        }
103	        if (!conflicts.isEmpty()) me.getContentionManager().resolveConflict(me, conflicts);
104	    }
105	
106	    public void resolveWriteConflict() {
107	        Transaction me = FortressTaskRunner.getTransaction();
108	        if (writer != null && writer.isActive() && !writer.isAncestorOf(me)) {
109	            me.getContentionManager().resolveConflict(me, writer);
110	        }
111	    }
112	
113	    public void resolveReadWriteConflicts() {
114	        resolveReadConflicts();
115	        resolveWriteConflict();
116	    }
117	}
