133	import java.util.AbstractSet;
134	import java.util.concurrent.CopyOnWriteArrayList;
135	
136	public class ReadSet extends AbstractSet<Transaction> {
137	    private CopyOnWriteArrayList<Transaction> elements;
138	    private Boolean sealed;
139	
140	    public ReadSet() {
141	        sealed = false;
142	        elements = new CopyOnWriteArrayList<Transaction>();
143	    }
144	
145	
146	    public ReadSet(ReadSet r) {
147	        sealed = false;
148	        elements = new CopyOnWriteArrayList<Transaction>();
149	        // There is a race here.  If I'm trying to copy from r and r is modified
150	        // out from underneath me, I get a NoSuchElementException, so I'm writing
151	        // my own add function.
152	        if (r != null) myAdd(r);
153	    }
154	
155	    private void myAdd(ReadSet r) {
156	        for (Transaction t : elements) {
157	            if (t.isActive()) elements.add(t);
158	        }
159	    }
160	
161	    public String toString() {
162	        return "sealed = " + sealed + " elements = " + elements;
163	    }
164	
165	
166	    /**
167	     * Initialize one object from another.
168	     *
169	     * @param aSet Initialize from this other object.
170	     */
171	    public void copyFrom(ReadSet aSet) {
172	        elements.addAll(aSet.elements);
173	    }
174	
175	    public void seal() {
176	        sealed = true;
177	    }
178	
179	    /**
180	     * Add a new transaction to the set.
181	     *
182	     * @param t Transaction to add.
183	     * @return Whether this transaction was already present.
184	     */
185	    public boolean add(Transaction t) {
186	        cleanup();
187	        if (sealed) {
188	            FortressTaskRunner.debugPrintln(
189	                    "add of " + t + " to readset " + toString() + " failed because readset was sealed");
190	            return false;
191	        } else {
192	            elements.addIfAbsent(t);
193	            return true;
194	        }
195	    }
196	
197	    public void cleanup() {
198	        for (Transaction t : elements) {
199	            if (!t.isActive()) remove(t);
200	        }
201	    }
202	
203	    /**
204	     * remove transaction from the set.
205	     *
206	     * @param t Transaction to remove.
207	     * @return Whether this transaction was already present.
208	     */
209	    public boolean remove(Transaction t) {
210	        boolean res = elements.contains(t);
211	        if (res) elements.remove(t);
212	        return res;
213	    }
214	
215	    /**
216	     * Discard all elements of this set.
217	     */
218	    public void clear() {
219	        elements.clear();
220	    }
221	
222	    /**
223	     * How many transactions in the set?
224	     *
225	     * @return Number of transactions in the set.
226	     */
227	    public int size() {
228	        return elements.size();
229	    }
230	
231	    /**
232	     * Iterate over transaction in the set.
233	     *
234	     * @return Iterator over transactions in the set.
235	     */
236	    public java.util.Iterator<Transaction> iterator() {
237	        return elements.iterator();
238	    }
239	}
