255	/**
256	 * Interface satisfied by all contention managers
257	 */
258	public interface ContentionManager {
259	    /**
260	     * Either give the writer a chance to finish it, abort it, or both.
261	     *
262	     * @param me    Calling transaction.
263	     * @param other Transaction that's in my way.
264	     */
265	    void resolveConflict(Transaction me, Transaction other);
266	
267	    /**
268	     * Either give the writer a chance to finish it, abort it, or both.
269	     *
270	     * @param me    Calling transaction.
271	     * @param other set of transactions in my way
272	     */
273	    void resolveConflict(Transaction me, Collection<Transaction> other);
274	
275	    /**
276	     * Assign a priority to caller. Not all managers assign meaningful priorities.
277	     *
278	     * @return Priority of conflicting transaction.
279	     */
280	    long getPriority();
281	
282	    /**
283	     * Change this manager's priority.
284	     *
285	     * @param value new priority value
286	     */
287	    void setPriority(long value);
288	
289	    /**
290	     * Notify manager that object was opened.
291	     */
292	    void openSucceeded();
293	
294	    /**
295	     * Notify manager that transaction committed.
296	     */
297	    void committed();
298	
299	    /**
300	     * Wait before trying again
301	     */
302	
303	    void waitToRestart();
304	
305	}
