321	import com.sun.fortress.interpreter.evaluator.transactions.Transaction;
322	
323	import java.util.Collection;
324	
325	/**
326	 * Greedy algorithm
327	 * There is an interesting interaction between work stealing and transactions.
328	 * Until we can figure out a way to boost the priority of the transaction keeping
329	 * everyone else waiting at a join point, this will have to do.
330	 */
331	
332	public class GreedyManager extends BaseManager {
333	
334	    public GreedyManager() {
335	    }
336	
337	    public void pickOne(Transaction me, Transaction other) {
338	        other.abort();
339	    }
340	
341	    public void pickOne(Transaction me, Collection<Transaction> others) {
342	        for (Transaction t : others) {
343	            t.abort();
344	        }
345	    }
346	
347	    public void resolveConflict(Transaction me, Transaction other) {
348	        if (me == null || other == null || !me.isActive() || !other.isActive()) return;
349	        pickOne(me, other);
350	    }
351	
352	    public void resolveConflict(Transaction me, Collection<Transaction> others) {
353	        if (me == null || !me.isActive()) return;
354	        pickOne(me, others);
355	    }
356	}

