package com.sun.fortress.runtimeSystem;

import java.util.concurrent.ForkJoinWorkerThread;
import java.util.concurrent.Callable;

public class FortressTaskRunner extends ForkJoinWorkerThread {

    public volatile BaseTask task;
    private int retries;
    private long elapsedTime = 0;
    private static long startTime = System.currentTimeMillis();

    public int retries() {
        return retries;
    }

    public long elapsedTime() {
        return elapsedTime;
    }

    public static void incRetries() {
        FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
        runner.retries += 1;
    }

    public static void resetRetries() {
        FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
        runner.retries = 0;
    }

    public static void incElapsedTime(long elapsedTime) {
        FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
        runner.elapsedTime += elapsedTime;
    }

    public static void resetElapsedTime() {
        FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
        runner.elapsedTime = 0;
    }

    public static void recordEndTransaction() {
        FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();        
        // When retries are reset, add the number of retries to a
        // tally in the group as well
        FortressTaskRunnerGroup ftrg = (FortressTaskRunnerGroup) runner.getPool();
        ftrg.addRetries(runner.retries());
        ftrg.addElapsedTime(runner.elapsedTime());
        resetRetries();
        resetElapsedTime();
    }

    public static int getRetries() {
        FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
        return runner.retries;
    }

    public BaseTask task() {
        return task;
    }

    public static BaseTask getTask() {
        FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
        return runner.task;
    }

    public static Transaction transaction() {
        return getTask().transaction();
    }

    public static boolean inATransaction() {
        return transaction() != null;
    }

    public void setTask(BaseTask t) {
        task = t;
    }

    public static void setCurrentTask(BaseTask task) {
        FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
        runner.setTask(task);
    }


    public FortressTaskRunner(FortressTaskRunnerGroup group) {
        super(group);
        retries = 0;
    }

    /**
     * Tests whether the current transaction can still commit.  Does not
     * actually end the transaction (either <code>commitTransaction</code> or
     * <code>abortTransaction</code> must still be called).  The contention
     * manager of the invoking thread is notified if the onValidate fails
     * because a <code>TMObject</code> opened for reading was invalidated.
     *
     * @return whether the current transaction may commit successfully.
     */

    public static void debugPrintln(String msg) {
        FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
        long t = System.currentTimeMillis() - startTime;
        System.out.println(runner.getName() + ":" + runner.getTask() + ":" + t + "ms " + msg);
    }

    /**
     * get thread ID for debugging
     *
     * @return unique id
     */
    public static int getID() {
        FortressTaskRunner runner = (FortressTaskRunner) Thread.currentThread();
        return runner.hashCode();
    }
}

package com.sun.fortress.runtimeSystem;
import java.util.concurrent.ForkJoinPool;

public class FortressTaskRunnerGroup extends ForkJoinPool {
    public static class FortressForkJoinWorkerThreadFactory implements ForkJoinWorkerThreadFactory {
        public FortressTaskRunner newThread(FortressTaskRunnerGroup group) {
            return new FortressTaskRunner(group);
        }

        public FortressTaskRunner newThread(ForkJoinPool pool) {
            return new FortressTaskRunner((FortressTaskRunnerGroup) pool);
        }
    }

    static final FortressForkJoinWorkerThreadFactory factory = new FortressForkJoinWorkerThreadFactory();

    private int allRetries = 0;
    private long totalElapsedTime = 0;

    public FortressTaskRunnerGroup(int groupSize) {
        // java.util.concurrent.ForkJoinPool has no (int, factory) constructor
        super(groupSize, factory, null, false);
    }

    public void addRetries(int retries) {
        this.allRetries += retries;
    }

    public void addElapsedTime(long elapsedTime) {
        this.totalElapsedTime += elapsedTime;
    }

    private static boolean envToBoolean(String s) {
        return s != null && s.length() > 0 &&
               s.substring(0,1).matches("[TtYy]");
    }

    public void printStatistics() {
        String printOnOutput = System.getenv("FORTRESS_THREAD_STATISTICS");
        if (envToBoolean(printOnOutput)) {
            System.out.println(toString());
            System.out.println("Had to retry a transaction " + this.allRetries + " times, " + 
                               "threads waited for a total of " + this.totalElapsedTime + " nanoseconds");
        }
    }
}

package com.sun.fortress.runtimeSystem;


import com.sun.fortress.nativeHelpers.systemHelper;
import java.util.concurrent.RecursiveAction;

/** Superclass of the generated component class.  We can't refer to
 *  that one until we have defined it and we need to pass an instance
 *  of it to the primordial task.  We need a run method here because
 *  the one in the generated class isn't visisble yet.
 */

public abstract class FortressExecutable extends RecursiveAction {
    public static final int numThreads = getNumThreads();
    public static final int defaultSpawnThreshold = 5;
    public static final int spawnThreshold = getSpawnThreshold();
    public static final int loopChunk = getLoopChunk();
    public static final FortressTaskRunnerGroup group =
        new FortressTaskRunnerGroup(numThreads);
    public static final boolean useHelpJoin = getHelpJoin();
    public static final boolean useExponentialBackoff = getBackoffStrategy();
    public static final boolean defaultBackoffExponential = false; // no evidence that it helps

    public static final int machineConstant = getMachineConst();

    public static int getNumThreads() {
        String numThreadsString = System.getenv("FORTRESS_THREADS");
        if (numThreadsString != null) return Integer.parseInt(numThreadsString);
        else {
            int availThreads = Runtime.getRuntime().availableProcessors();
            if (availThreads <= 2) return availThreads;
            else return (int) Math.floor((double) availThreads / 2.0);
        }
    }

    static int getSpawnThreshold() {
        String spawnThresholdString = System.getenv("FORTRESS_SPAWN_THRESHOLD");
        if (spawnThresholdString != null) return Integer.parseInt(spawnThresholdString);
        return defaultSpawnThreshold;
    }

    static int getLoopChunk() {
        String loopChunkString = System.getenv("FORTRESS_LOOP_CHUNK");
        if (loopChunkString != null) return Integer.parseInt(loopChunkString);
        return 1;
    }

    static boolean getHelpJoin() {
        String getHelpJoinString = System.getenv("FORTRESS_HELP_JOIN");
        return envToBoolean(getHelpJoinString);
    }

    static boolean getBackoffStrategy() {
        String backoffStrategyString = System.getenv("FORTRESS_EXP_BACKOFF");
        if (backoffStrategyString != null) return envToBoolean(backoffStrategyString);
        return useExponentialBackoff;
    }

